deepml vfx 0.3
module corpus.deepml_vfx.example_00251
policy deterministic
policy no_network
particle_system Effect00251 {
  emitter Main rate 71/s lifetime 4s seed 251
  attribute position: vec3
  attribute velocity: vec3
  force gravity vec3(0,-9.81,0)
  shader node ColorOverLife { input age output color }
  material PortalMat { shader: ColorOverLife blend: additive }
  light Glow { intensity: 6.0 color: rgb(0.2,0.5,1.0) }
}
render_pass MainPass inputs [Effect00251] target Color
composite Color over SceneColor

